"""Node and transition helpers in the shapes the platform is known to accept (docs/workflow-format.md)."""


def _grp(conds):
    return {"logic": "or", "conditions": conds}


def eq(target, var, val, desc=None):
    return {"target_node": target, "description": desc or f"{var} is {val}", "condition": _grp([{"variable": var, "operator": "equals", "operand": str(val)}])}


def any_eq(target, var, vals, desc=None):
    return {"target_node": target, "description": desc or f"{var} is one of {', '.join(map(str, vals))}",
            "condition": _grp([{"variable": var, "operator": "equals", "operand": str(v)} for v in vals])}


def is_true(target, var, desc=None):
    """Booleans arrive as 'true' or 'True'. Test both."""
    return any_eq(target, var, ["true", "True"], desc or f"{var} is true")


def greater(target, var, n, desc=None):
    return {"target_node": target, "description": desc or f"{var} > {n}", "condition": _grp([{"variable": var, "operator": "greater_than", "operand": n}])}


def and_eq(target, pairs_options, desc):
    """OR over several AND groups. `pairs_options` is a list of [(var, val), ...] lists."""
    return {"target_node": target, "description": desc, "condition": _grp([
        {"logic": "and", "conditions": [{"variable": v, "operator": "equals", "operand": str(x)} for v, x in pairs]} for pairs in pairs_options])}


def intent(target, desc):
    return {"target_node": target, "description": desc, "condition": {"operator": "matches_intent", "description": desc}}


def always(target, desc="always"):
    return {"target_node": target, "description": desc, "condition": {"operator": "always"}}


def enum_field(name, values, description, min_confidence=0.6):
    return {"name": name, "type": "string", "enum_values": list(values), "description": description, "min_confidence": min_confidence}


def conversation(name, task, transitions, tools=(), extract=(), on_enter=None, first_entry_only=True, max_turns=None, max_turn_target=None):
    n = {"name": name, "node_type": "conversation", "task_message": task, "transitions": list(transitions)}
    if on_enter:
        n["on_enter"] = on_enter
        n["on_enter_first_entry_only"] = first_entry_only
    if tools:
        n["tools"] = list(tools)
    if extract:
        n["extraction_schema"] = list(extract)
    if max_turns:
        n["max_node_turns"] = max_turns
        if max_turn_target:
            n["max_turn_transition"] = max_turn_target
    return n


def code(name, source, next_node, transitions=()):
    if "{{" in source or "}}" in source:
        raise ValueError(f"code node {name}: '{{{{' or '}}}}' in source")
    return {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": next_node,
            "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
            "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec", "parameters": {
                "type": "object", "properties": {"code": {"type": "string", "default": source}, "timeout_ms": {"type": "number", "default": 10000}}}}}],
            "transitions": list(transitions) + [always(next_node)]}


def api_request(name, pre_action, next_node, transitions=(), mapping=(), say=None):
    n = {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": next_node,
         "on_enter": {"type": "tts", "text": say} if say else {"type": "silent"}, "disable_inactivity_monitor": True,
         "pre_actions": [pre_action], "transitions": list(transitions) + [always(next_node)]}
    if mapping:
        n["response_mapping"] = [{"path": p, "variable": v} for p, v in mapping]
    return n


def end(name="end", function_name="call_closed"):
    """Hangs up silently. The farewell is spoken by the node before it."""
    return {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "transitions": [],
            "terminal": {"type": "function", "function": {"name": function_name, "handler": "__function__:end_call",
                                                          "parameters": {"type": "object", "properties": {"message_mode": {"type": "string", "default": "none"}}}}}}


def close(api, name, outcome, reason, farewell, end_node="end"):
    """Says the farewell, then records the outcome with close_call, then hangs up.

    The outcome is baked as a literal: no model call, no code sandbox, no variable that might be unset.
    close_call is idempotent enough to retry: the API says a 500 recorded nothing."""
    values = {api.close_outcome: outcome}
    if reason:
        values[api.close_reason] = reason
    return api_request(name, api.pre_action(api.close_op, values, retries=2), end_node, say=farewell)


def close_from_vars(api, name, farewell, outcome_var="final_outcome", reason_var="final_reason", end_node="end"):
    """Like close(), for an outcome a code node computed. A reason variable that was never set is not sent.

    Give the code node that computes the outcome a first transition `unset(fallback, outcome_var)` to a literal close:
    if the sandbox dropped the code, the outcome is unset and the call still closes."""
    values = {api.close_outcome: "{{%s}}" % outcome_var, api.close_reason: "{{%s}}" % reason_var}
    return api_request(name, api.pre_action(api.close_op, values, retries=2), end_node, say=farewell)



def unset(target, var, desc=None):
    return {"target_node": target, "description": desc or f"{var} is not set", "condition": _grp([{"variable": var, "operator": "is_not_set"}])}

"""Python source for code nodes. Parameters go in as a JSON string literal, never with braces in the source."""
import json

CALENDAR = r'''import datetime
import json
import re
P = json.loads(PARAMS)
HOL = set(P.get('holidays') or [])
WEEKEND = set(P.get('weekend_days') if P.get('weekend_days') is not None else [5, 6])
DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MONS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
ONE = datetime.timedelta(days=1)
def isbiz(d):
    return d.weekday() not in WEEKEND and d.isoformat() not in HOL
def say(d):
    return DAYS[d.weekday()] + ' ' + str(d.day) + ' ' + MONS[d.month - 1] + ' ' + str(d.year)
def nextbiz(d):
    x = d + ONE
    while not isbiz(x):
        x = x + ONE
    return x
def nth_biz_after(d, n):
    x = d
    for i in range(n):
        x = nextbiz(x)
    return x
def read_list(node, field):
    # A list from an api_request result. A node-level mapping of a list did not arrive in practice;
    # the flattened keys <node>_response.data.<field>.<i>.<key> did. Try the mapped variable first, then those keys.
    v = vars.get(field)
    if isinstance(v, str):
        try:
            v = json.loads(v)
        except Exception:
            v = None
    if isinstance(v, list) and v:
        return v
    found = dict()
    pat = re.compile('^' + re.escape(node) + r'_response\.data\.' + re.escape(field) + r'\.(\d+)\.(\w+)$')
    for k in list(vars.keys()):
        m = pat.match(str(k))
        if m:
            found.setdefault(int(m.group(1)), dict())[m.group(2)] = vars.get(k)
    return [found[i] for i in sorted(found)]
def num(x, default=0.0):
    try:
        return float(str(x).replace(',', ''))
    except Exception:
        return default
def money(x):
    x = num(x)
    return str(int(round(x))) if abs(x - round(x)) < 0.005 else '%.2f' % x
def get_now():
    s = str(vars.get('now') or '').strip().replace(' ', 'T')
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        return datetime.datetime.fromisoformat(s[:10] + 'T10:00')
'''


def with_params(body, params):
    """Prefix `body` with the calendar helpers and a PARAMS JSON string. Raises if braces would end up in the source."""
    lit = json.dumps(json.dumps(params))
    lit = lit.replace("{", "\\x7b").replace("}", "\\x7d")
    src = "PARAMS = " + lit + "\n" + CALENDAR + body
    if "{{" in src or "}}" in src:
        raise ValueError("braces in generated code")
    return src


def run_locally(src, variables):
    """Run a snippet the way the platform does: a `vars` dict in, the same dict out. For tests."""
    env = {"vars": dict(variables)}
    exec(compile(src, "<code node>", "exec"), env)
    return env["vars"]

"""Read the bank's tool API file and turn its operations into Freya tool definitions."""
import json
import re

HDR = {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}}
# Body fields the model may see. Everything that is not here is baked from a variable or a literal.
_SCHEMA_KEYS = ("type", "description", "enum")


class Api:
    """One tool API file. `ops[name]` holds the request fields, the required list and the response fields."""

    def __init__(self, path):
        self.doc = json.load(open(path))
        self.base_url = (self.doc.get("servers") or [{}])[0].get("url", "").rstrip("/")
        self.ops = {}
        for p, methods in self.doc.get("paths", {}).items():
            for method, op in methods.items():
                name = op.get("operationId") or p.strip("/").split("/")[-1]
                req = self._resolve(op.get("requestBody", {}).get("content", {}).get("application/json", {}).get("schema", {}))
                ok = op.get("responses", {}).get("200", {}).get("content", {}).get("application/json", {}).get("schema", {})
                self.ops[name] = {"path": p, "method": method.upper(), "fields": req.get("properties", {}),
                                  "required": req.get("required", []), "response": self._resolve(ok).get("properties", {}),
                                  "summary": op.get("summary", "")}
        self._find_roles()

    def _find_roles(self):
        """Names the kit needs but must not assume. Found in the file; `roles` can be overridden on the instance.

        id_field    the field every request carries (the customer), baked from the variable of the same name
        close_op    the operation that ends the call, close_outcome / close_reason its two fields"""
        reqs = [set(o["required"]) for o in self.ops.values() if o["required"]]
        common = set.intersection(*reqs) if reqs else set()
        ids = sorted(c for c in common if c.endswith("id")) or sorted(common)
        self.id_field = ids[0] if ids else "customer_id"
        names = list(self.ops)
        pick = ([n for n in names if re.search(r"close|hang", n, re.I)]
                + [n for n in names if re.search(r"end the call|last tool call", self.ops[n]["summary"], re.I)]
                + [n for n in names if re.search(r"(^|_)end(_|$)", n, re.I)])
        self.close_op = pick[0] if pick else "close_call"
        fields = self.ops.get(self.close_op, {}).get("fields", {})
        enum_fields = [f for f, sch in fields.items() if f != self.id_field and self._resolve(sch).get("enum")]
        others = [f for f in fields if f != self.id_field and f not in enum_fields]
        self.close_outcome = enum_fields[0] if enum_fields else "outcome"
        self.close_reason = others[0] if others else "reason"

    def ok_field(self, op):
        """The boolean in a response that says the call was carried out (ok, success, ...)."""
        props = self.ops.get(op, {}).get("response", {})
        for name in ("ok", "success"):
            if name in props:
                return name
        for name, sch in props.items():
            if self._resolve(sch).get("type") == "boolean":
                return name
        return "ok"

    def _resolve(self, s):
        """Follow a local $ref (#/components/...) one level at a time."""
        while isinstance(s, dict) and "$ref" in s:
            node = self.doc
            for part in s["$ref"].lstrip("#/").split("/"):
                node = node.get(part, {})
            s = node
        return s or {}

    def enum(self, op, field):
        return list(self._resolve(self.ops[op]["fields"].get(field, {})).get("enum", []))

    def url(self, op):
        return self.base_url + self.ops[op]["path"]

    def _body(self, op, baked, model_fields, descriptions):
        props = {}
        for f, s in self.ops[op]["fields"].items():
            s = self._resolve(s)
            leaf = {k: s[k] for k in _SCHEMA_KEYS if k in s}
            leaf.setdefault("type", "string")
            if f in baked:
                leaf["default"] = baked[f]
            elif model_fields is None or f in model_fields:
                # a placeholder no variable carries: the model fills it, and the field shows with its enum and description
                leaf["default"] = "{{%s}}" % f
                if f in descriptions:
                    leaf["description"] = descriptions[f]
            else:
                continue
            props[f] = leaf
        return {"type": "object", "properties": props, "required": [f for f in self.ops[op]["required"] if f in props]}

    def tool(self, op, description, baked=None, model_fields=None, descriptions=None, post_code="", retries=0, timeout_ms=12000):
        """A tool for a conversation node's `tools`. `baked` fields are fixed ({{var}} or literal), the rest the model fills."""
        baked = dict(baked or {})
        if self.id_field in self.ops[op]["fields"]:
            baked.setdefault(self.id_field, "{{%s}}" % self.id_field)
        t = {"type": "function", "config": {"timeoutMs": timeout_ms, "maxRetries": retries},
             "function": {"name": op, "handler": "__function__:api_call", "description": description,
                          "parameters": {"type": "object", "properties": {
                              "url": {"type": "string", "default": self.url(op)},
                              "method": {"type": "string", "default": self.ops[op]["method"]},
                              "headers": HDR,
                              "body": self._body(op, baked, model_fields, descriptions or {})}}}}
        if post_code:
            t["post_process_code"] = post_code
        return t

    def pre_action(self, op, values, retries=2, timeout_ms=12000):
        """An engine-run call for an api_request node. Every field is baked; a field left out of `values` is not sent."""
        values = dict(values)
        if self.id_field in self.ops[op]["fields"]:
            values.setdefault(self.id_field, "{{%s}}" % self.id_field)
        t = self.tool(op, "", baked=values, model_fields=(), retries=retries, timeout_ms=timeout_ms)
        del t["function"]["description"]
        return t

"""Local checks on a workflow before it goes to the platform. Returns a list of problems; empty means clean."""
import json

PROMISE_OP = "create_promise"      # the seven tool names stay the same in every brief (hackathon page)


def _has_null(o):
    """A real null in the structure. The word null inside a code string is fine."""
    if o is None:
        return True
    if isinstance(o, dict):
        return any(_has_null(v) for v in o.values())
    if isinstance(o, list):
        return any(_has_null(v) for v in o)
    return False


def lint(wf, api=None):
    errs = []
    nodes = wf.get("nodes", {})
    if wf.get("initial_node") not in nodes:
        errs.append(f"initial_node {wf.get('initial_node')!r} is not a node")
    if "agent_config" in wf:
        errs.append("agent_config must be left out")
    if _has_null(wf):
        errs.append("a null value (the schema rejects null)")
    allnodes = {**nodes, **wf.get("global_nodes", {})}
    for k, n in allnodes.items():
        t = n.get("node_type", "conversation")
        for tr in n.get("transitions", []):
            if tr.get("target_node") not in allnodes and tr.get("target_node") != "__previous__":
                errs.append(f"{k}: transition to missing node {tr.get('target_node')!r}")
        for f in ("max_turn_transition", "passthrough_default_transition"):
            if n.get(f) and n[f] not in allnodes and n[f] != "__previous__":
                errs.append(f"{k}: {f} to missing node {n[f]!r}")
        if n.get("tools") and t != "conversation":
            errs.append(f"{k}: tools on a {t} node are dropped by the platform")
        if n.get("pre_actions") and t == "conversation":
            errs.append(f"{k}: pre_actions on a conversation node are dropped by the platform")
        if n.get("passthrough") and not any(tr.get("condition", {}).get("operator") == "always" for tr in n.get("transitions", [])):
            errs.append(f"{k}: passthrough node without an always transition deadlocks")
        if t == "end_call" and n.get("transitions"):
            errs.append(f"{k}: end_call node with transitions")
        if t == "conversation" and not (n.get("task_message") or "").strip():
            errs.append(f"{k}: empty task_message")
        for e in n.get("extraction_schema", []):
            if "min_confidence" not in e:
                errs.append(f"{k}: extraction field {e.get('name')} without min_confidence")
        for a in n.get("pre_actions", []):
            if a["function"]["handler"].endswith("code_exec"):
                src = a["function"]["parameters"]["properties"]["code"]["default"]
                if "{{" in src or "}}" in src:
                    errs.append(f"{k}: '{{{{' or '}}}}' in code")
                try:
                    compile(src, k, "exec")
                except SyntaxError as e:
                    errs.append(f"{k}: code does not compile: {e}")
        for tool in n.get("tools", []) + n.get("pre_actions", []):
            for hook in ("pre_process_code", "post_process_code"):
                if tool.get(hook):
                    try:
                        compile(tool[hook], f"{k}.{hook}", "exec")
                    except SyntaxError as e:
                        errs.append(f"{k}: {hook} of {tool['function']['name']} does not compile: {e}")
            if "const" in json.dumps(tool):
                errs.append(f"{k}: 'const' in tool {tool['function']['name']} is never sent")
        if api:
            for a in n.get("pre_actions", []):
                if a["function"]["name"] == api.close_op:
                    body = a["function"]["parameters"]["properties"]["body"]["properties"]
                    out = body.get(api.close_outcome, {}).get("default")
                    allowed = api.enum(api.close_op, api.close_outcome)
                    if allowed and out not in allowed and not str(out).startswith("{{"):
                        errs.append(f"{k}: {api.close_op} outcome {out!r} not in the tool API ({', '.join(allowed)})")
                # A promise the bank did not take must not end where a recorded one does: the customer would hear it was
                # recorded (honesty). Seen on 11 October: a hand-added second instalment went to the promise close either way.
                if a["function"]["name"] == PROMISE_OP and n.get("node_type") == "api_request":
                    ok_targets = {tr.get("target_node") for tr in n.get("transitions", []) if f"{k}_response" in json.dumps(tr.get("condition"))}
                    fail = n.get("passthrough_default_transition")
                    if fail in ok_targets:
                        errs.append(f"{k}: a failed {PROMISE_OP} goes to {fail!r}, the same step as a recorded one; "
                                    "the failure path must retry or say what could not be recorded")
    reach, todo = set(), [wf.get("initial_node")]
    while todo:
        k = todo.pop()
        if k in reach or k not in allnodes:
            continue
        reach.add(k)
        n = allnodes[k]
        todo += [tr.get("target_node") for tr in n.get("transitions", [])] + [n.get("max_turn_transition"), n.get("passthrough_default_transition")]
    for k in nodes:
        if k not in reach:
            errs.append(f"{k}: not reachable from the initial node")
    if not any(n.get("node_type") == "end_call" for n in nodes.values()):
        errs.append("no end_call node")
    return errs

