COMMON = r'''
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AYLAR = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    s = []
    if h:
        s.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
    if t:
        s.append(TENS[t])
    if o:
        s.append(ONES[o])
    return ' '.join(s)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((10**9, 'milyar'), (10**6, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            if val == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(w3(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)
def split(x):
    c = int(round(abs(num(x)) * 100))
    return c // 100, c % 100
CUR = dict(TL=('Türk Lirası', 'lira', 'kuruş'), USD=('Dolar', 'dolar', 'sent'), EUR=('Euro', 'euro', 'sent'), GBP=('İngiliz Sterlini', 'sterlin', 'peni'))
def amt(x, cur):
    full, unit, sub = CUR[cur]
    a, b = split(x)
    if b == 0:
        return words(a) + ' ' + (full if cur == 'TL' else unit)
    return words(a) + ' ' + unit + ' ' + words(b) + ' ' + sub
def dir_(w):
    w = w.strip()
    vs = [ch for ch in w.lower() if ch in 'aıeioöuü']
    v = vs[-1] if vs else 'e'
    hv = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    c = 't' if w[-1].lower() in 'fstkçşhp' else 'd'
    return w + "'" + c + hv + 'r'
def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
